// English reading text sourced from existing Sottovoce/Opera Guide transcription.
// Russian column intentionally blank: no aligned Russian original has been verified.
export const oneginAct1Scenes=[{"number":1,"originalHeading":"","translatedHeading":"Act 1 — English text","summary":"English-language reading text. Russian lyrics not supplied; no equivalence asserted.","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"Have you not heard, from beyond the grove at night,","participants":["TATYANA, OLGA","LARINA","FILIPYEVNA","LARINA, FILIPYEVNA"],"sourceStartIndex":0,"sourceLineCount":65,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Introduction\nThe garden of the Larin country estate. On the left a house with a terrace; on the right, a shady tree. It is early evening.\nMadame Larina is sitting under the tree making jam on qa portable stove; Filipyevna is helping her. The doors leading from the house onto the terrace are open and the voices of the two girls, singing a duet, can be heard coming from within.","literalText":true,"sourceStartIndex":0,"sourceLineCount":3},{"speaker":"TATYANA, OLGA","speakerTranslation":"TATYANA, OLGA","original":"","translation":"Have you not heard, from beyond the grove at night,\nthe voice that sings of love and sings of sorrow?\nWhen, at the morning hour, the fields lay silent,\nthe music of the pipe, simple and sad,\nhave you not heard? …\nThen the music of the pipe, simple and sad,\nhave you not heard? …","literalText":true,"sourceStartIndex":3,"sourceLineCount":7},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"They are singing, and I, too,\nUsed to sing that song in days gone by.\nDo you remember? I used to sing it too.","literalText":true,"sourceStartIndex":10,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"You were young then.","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The duet continues as the older women chat and reminisce.","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"TATYANA, OLGA","speakerTranslation":"TATYANA, OLGA","original":"","translation":"Have you not sighed\nOn hearing that sweet voice\nsing of love\nand of its sorrows?\nWhen in the forest …","literalText":true,"sourceStartIndex":15,"sourceLineCount":5},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"How I loved Richardson!","literalText":true,"sourceStartIndex":20,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"You were young then.","literalText":true,"sourceStartIndex":21,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Not that I'd read his books.\nbut in the old days Princess Alina.\nmy cousin in Moscow,\nkept on to me about him.","literalText":true,"sourceStartIndex":22,"sourceLineCount":4},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Yes, I remember.","literalText":true,"sourceStartIndex":26,"sourceLineCount":1},{"speaker":"TATYANA, OLGA","speakerTranslation":"TATYANA, OLGA","original":"","translation":"… you saw a youth\nand met the gaze\nof his sunken eyes …","literalText":true,"sourceStartIndex":27,"sourceLineCount":3},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Ah, Grandison! Ah, Richardson!","literalText":true,"sourceStartIndex":30,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"At that time your husband\nwas still courting you, but against your will;\nyou were dreaming of another,\none who pleased you much more\nin heart and mind!","literalText":true,"sourceStartIndex":31,"sourceLineCount":5},{"speaker":"TATYANA, OLGA","speakerTranslation":"TATYANA, OLGA","original":"","translation":"… did you not sigh? Did you not sigh? etc.","literalText":true,"sourceStartIndex":36,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Ah, Richardson!\nWhy, he was a fine dandy,\na gambler and an ensign in the Guards!","literalText":true,"sourceStartIndex":37,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Years long gone by!","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"How well I always used to dress!","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Always in the latest fashion!","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Always in the fashion and becomingly!","literalText":true,"sourceStartIndex":43,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Always in the fashion and becomingly!","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"TATYANA, OLGA","speakerTranslation":"TATYANA, OLGA","original":"","translation":"… Did you not sigh,\nwhen you met the gaze\nof his sunken eyes,\ndid you not sigh, did you not sigh, etc.","literalText":true,"sourceStartIndex":45,"sourceLineCount":4},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"But suddenly, without even asking me …","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"… They married you off without further ado!\nThen, to relieve your unhappiness …","literalText":true,"sourceStartIndex":50,"sourceLineCount":2},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Oh, how I cried to begin with!\nI nearly left my husband!","literalText":true,"sourceStartIndex":52,"sourceLineCount":2},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"… the master came straight here.\nHere you busied yourself with the household,\nbecame resigned and settled down.","literalText":true,"sourceStartIndex":54,"sourceLineCount":3},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"I busied myself with the household,\nbecame resigned and settled down.","literalText":true,"sourceStartIndex":57,"sourceLineCount":2},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"And God be thanked!","literalText":true,"sourceStartIndex":59,"sourceLineCount":1},{"speaker":"LARINA, FILIPYEVNA","speakerTranslation":"LARINA, FILIPYEVNA","original":"","translation":"Habit is sent us from above\nin place of happiness.\nYes, that is how it is:\nHabit is sent us from above,\nin place of happiness.","literalText":true,"sourceStartIndex":60,"sourceLineCount":5}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"Corset, album, Princess Pauline,","participants":["LARINA","FILIPYEVNA","LARINA, FILIPYEVNA","PEASANT LEADER","PEASANTS","LEADER"],"sourceStartIndex":65,"sourceLineCount":45,"turns":[{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Corset, album, Princess Pauline,\nthe book of sentimental verse,\nI forgot them all.","literalText":true,"sourceStartIndex":65,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"You began\nto call the maid Akulka instead of “Céline”\nand restored at last …","literalText":true,"sourceStartIndex":68,"sourceLineCount":3},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Ah …","literalText":true,"sourceStartIndex":71,"sourceLineCount":1},{"speaker":"LARINA, FILIPYEVNA","speakerTranslation":"LARINA, FILIPYEVNA","original":"","translation":"… the quilted dressing gown and mob cap!\nHabit is sent us from above,\nin place of happiness.\nYes, that is how it is:\nhabit is sent us from above,\nin place of happiness.","literalText":true,"sourceStartIndex":72,"sourceLineCount":6},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"But my husband loved me truly …","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"But the master loved you truly …","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"… and trusted me unreservedly.","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"… And trusted you unreservedly.","literalText":true,"sourceStartIndex":81,"sourceLineCount":1},{"speaker":"LARINA, FILIPYEVNA","speakerTranslation":"LARINA, FILIPYEVNA","original":"","translation":"Habit is sent us from above,\nin place of happiness.","literalText":true,"sourceStartIndex":82,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The singing of an approaching band of peasants is heard in the distance.","literalText":true,"sourceStartIndex":84,"sourceLineCount":1},{"speaker":"PEASANT LEADER","speakerTranslation":"PEASANT LEADER","original":"","translation":"My swift little feet ache from walking.","literalText":true,"sourceStartIndex":85,"sourceLineCount":1},{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"... Ache from walking.","literalText":true,"sourceStartIndex":86,"sourceLineCount":1},{"speaker":"LEADER","speakerTranslation":"LEADER","original":"","translation":"My white hands ache from working.","literalText":true,"sourceStartIndex":87,"sourceLineCount":1},{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"… Ache from working.\nMy ardent heart aches from caring.\nI don't know what to do,\nhow to forget my sweetheart.\nMy swift little feet, etc.","literalText":true,"sourceStartIndex":88,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The peasant band enters, the leaders bearing a decorated sheaf.","literalText":true,"sourceStartIndex":93,"sourceLineCount":1},{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"Greetings, your ladyship,\ngreetings, benefactress!\nWe come before your Grace\nbearing the decorated sheaf!\nThe harvest is all gathered in!","literalText":true,"sourceStartIndex":94,"sourceLineCount":5},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"So, that's excellent. Now make merry!\nI'm pleased to see you all.\nSing us something jolly!","literalText":true,"sourceStartIndex":99,"sourceLineCount":3},{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"If that's what you'd like, little mother!\nCome, let's entertain the lady.\nNow, girls, stand in a ring!\nCome along now, all get ready!","literalText":true,"sourceStartIndex":102,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The girls form a circle and dance around the sheaf. During the singing, Tatyana and Olga come out onto the balcony.","literalText":true,"sourceStartIndex":106,"sourceLineCount":1},{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"One day across the bridge, the little bridge,\nalong the hazel planks,\nVayinu, vayinu, vayinu, vayinu,","literalText":true,"sourceStartIndex":107,"sourceLineCount":3}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"along the hazel planks,","participants":["PEASANTS","TATYANA","OLGA","LARINA"],"sourceStartIndex":110,"sourceLineCount":65,"turns":[{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"along the hazel planks,\ncame a fine young fellow,\nfresh and ruddy as a raspberry,\nVayinu …\nfresh and ruddy as a raspberry.\nOver his shoulder he carries a cudgel,\nunder one coat-skirt he carries bagpipes,\nVayinu …\nunder one coat-skirt he carries bagpipes,\nunder the other is a fiddle.\nNow just you guess, my dearest,\nVayinu …\nNow just you guess, my dearest.\nThe sun has set, aren't you asleep, then?\nCome out yourself or else send out,\nVayinu …\nCome out yourself or else send out\nSasha or Masha\nor dear little Parasha,\nVayinu …\nSend dear little Parasha,\nSasha, etc.\nParashenka came out,\nand had a talk with her sweetheart\nVayinu …\nhad a talk with her sweetheart:\n“Don't grumble at me, my dearest,\nI've come out just as I was,\nin my shabby little blouse\nand my short skirt.\nVayinu …\nIn my shabby little blouse\nand my short skirt!\nDon't you grumble at me, etc.”\nVayinu, etc.","literalText":true,"sourceStartIndex":110,"sourceLineCount":35},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"a book in her hand","literalText":true,"sourceStartIndex":145,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"How I love to dream when I hear these songs,\nand float away\nsomewhere, somewhere far off!","literalText":true,"sourceStartIndex":146,"sourceLineCount":3},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"Ah, Tanya, Tanya!\nYou're always dreaming!\nBut I am quite unlike you,\nI feel merry when I hear singing.","literalText":true,"sourceStartIndex":149,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"dancing a few steps","literalText":true,"sourceStartIndex":153,"sourceLineCount":1},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"'Across the bridge, the little bridge,\nalong the hazel planks …'\nI was not made for melancholy singing,\nI do not like to dream in silence,\nnor, on the balcony in the dark night,\nto sigh, to sigh,\nto sigh from the depths of my soul.\nWhy should I sigh, when full of happiness,\nmy youthful days flow gently by?\nI am carefree and full of fun,\nand everyone calls me a child!\nFor me life will always, always be sweet,\nand I shall retain, as I always have,\nlight-hearted confidence,\nbe playful, carefree, merry!\nLight-hearted confidence, etc.\nI was not made for melancholy sighing, etc.","literalText":true,"sourceStartIndex":154,"sourceLineCount":17},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Well, my frolicsome one,\nmerry and playful little bird that you are,\nI expect you're ready to dance now,\nisn't that so?","literalText":true,"sourceStartIndex":171,"sourceLineCount":4}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"Tanyusha! Hey, Tanyusha!","participants":["FILIPYEVNA","TATYANA","LARINA","PEASANTS","OLGA","LENSKY","ONEGIN"],"sourceStartIndex":175,"sourceLineCount":62,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Filipyevna and Tatyana have moved away from the others.","literalText":true,"sourceStartIndex":175,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Tanyusha! Hey, Tanyusha!\nIs anything the matter?\nYou're not ill, are you?","literalText":true,"sourceStartIndex":176,"sourceLineCount":3},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"No, nurse, I’m quite well.","literalText":true,"sourceStartIndex":179,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"to the peasants","literalText":true,"sourceStartIndex":180,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Well, my dears, thank you for the songs.\nGo over to the annexe.","literalText":true,"sourceStartIndex":181,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"to Filipyevna","literalText":true,"sourceStartIndex":183,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Filipyevna , see that they have some wine.\nGoodbye, my friends!","literalText":true,"sourceStartIndex":184,"sourceLineCount":2},{"speaker":"PEASANTS","speakerTranslation":"PEASANTS","original":"","translation":"Goodbye, little mother!","literalText":true,"sourceStartIndex":186,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"They leave, accompanied by Filipyevna.\nTatyana sits down on the steps of the terrace and becomes engrossed in her book.","literalText":true,"sourceStartIndex":187,"sourceLineCount":2},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"Mama, just look at Tanya!","literalText":true,"sourceStartIndex":189,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"What is it? Indeed, my dear,\nyou're very pale.","literalText":true,"sourceStartIndex":190,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"I always am,\ndon't worry, Mama!\nIt's very interesting, this book I'm reading.","literalText":true,"sourceStartIndex":192,"sourceLineCount":3},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Is that why you're so pale?","literalText":true,"sourceStartIndex":195,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Why yes, of course, Mama!\nThe account of the torments\nsuffered by these true lovers moves me;\nI'm so sorry for them, poor things!\nOh, how they suffer, how they suffer!","literalText":true,"sourceStartIndex":196,"sourceLineCount":5},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"That's enough, Tanya!\nI used to get upset, just like you,\nwhen I read such books.\nIt's only fiction. As the years went by,\nI came to see that there are no heroes in real life.\nNow I take things calmly.","literalText":true,"sourceStartIndex":201,"sourceLineCount":6},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"You shouldn't take things quite so calmly!\nLook, you've forgotten to take off your apron!\nSupposing Lensky should arrive, what then?\nMme Larina hastily removes her apron.\nListen! Someone's coming, it's him!","literalText":true,"sourceStartIndex":207,"sourceLineCount":5},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"It is indeed!","literalText":true,"sourceStartIndex":212,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"looking down from the terrace","literalText":true,"sourceStartIndex":213,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"He's not alone …","literalText":true,"sourceStartIndex":214,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Who could it be?","literalText":true,"sourceStartIndex":215,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"hurriyng in","literalText":true,"sourceStartIndex":216,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Madam, the young gentleman Lensky has arrived.\nMr. Onegin is with him!","literalText":true,"sourceStartIndex":217,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Oh, quick, I'll run away!","literalText":true,"sourceStartIndex":219,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"restraining her","literalText":true,"sourceStartIndex":220,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Where are you off to, Tanya?\nPeople will talk!\nGracious, my cap's on crooked!","literalText":true,"sourceStartIndex":221,"sourceLineCount":3},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"Have them shown in, then!","literalText":true,"sourceStartIndex":224,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"to Filipyevna","literalText":true,"sourceStartIndex":225,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Quick, ask them to come in!","literalText":true,"sourceStartIndex":226,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Filipyevna bustles out. The others, in extreme excitement, prepare to receive the guests. Lensky and Onegin are shown in. Lensky kisses Mme Larina’s hand and bows politely to the girls.","literalText":true,"sourceStartIndex":227,"sourceLineCount":1},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Mesdames! I've taken the liberty\nof bringing a friend along.\nMay I introduce Onegin, my neighbour.","literalText":true,"sourceStartIndex":228,"sourceLineCount":3},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"I'm very honoured.","literalText":true,"sourceStartIndex":231,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"rather flustered","literalText":true,"sourceStartIndex":232,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Oh please … We're delighted to see you …\nDo sit down!\nThese are my daughters.","literalText":true,"sourceStartIndex":233,"sourceLineCount":3},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"I'm very happy to meet you!","literalText":true,"sourceStartIndex":236,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"Come into the house …","participants":["LARINA","LENSKY","ONEGIN","TATYANA","OLGA"],"sourceStartIndex":237,"sourceLineCount":65,"turns":[{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Come into the house …\nOr perhaps you'd prefer\nto stay out of doors?\nI beg you,\ndon't stand on ceremony; we’re neighbours,\nso there's no need for formality!","literalText":true,"sourceStartIndex":237,"sourceLineCount":6},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"It's delightful here! I love\nthis garden, so shady and secluded,\none is so comfortable here!","literalText":true,"sourceStartIndex":243,"sourceLineCount":3},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"That's splendid!\nI'll go and see to things in the house","literalText":true,"sourceStartIndex":246,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"to the girls","literalText":true,"sourceStartIndex":248,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"You entertain our guests.\nI won't be long.","literalText":true,"sourceStartIndex":249,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She leaves, making a sign to Tatyana not to be shy.\nLensky and Onegin walk over to the right, conversing;\nTatyana and Olga stand on the opposite side, soliloquizing.","literalText":true,"sourceStartIndex":251,"sourceLineCount":3},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"Tell me, which is Tatyana?\nI'm very curious to know.","literalText":true,"sourceStartIndex":254,"sourceLineCount":2},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Why, the one who is sad\nand silent, like Svetlana!","literalText":true,"sourceStartIndex":256,"sourceLineCount":2},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"Can you really be in love with the younger one?","literalText":true,"sourceStartIndex":258,"sourceLineCount":1},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Why?","literalText":true,"sourceStartIndex":259,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"I should have chosen the other,\nhad I been, like you, a poet!","literalText":true,"sourceStartIndex":260,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"My waiting is over, my eyes have been opened!\nI know, I know that this is he!","literalText":true,"sourceStartIndex":262,"sourceLineCount":2},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"Oh, I knew, I knew that the appearance\nof Onegin would make\na great impression on everyone\nand give the neighbours plenty to talk about!\nThere will be no end to the conjectures …","literalText":true,"sourceStartIndex":264,"sourceLineCount":5},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Ah, my friend …","literalText":true,"sourceStartIndex":269,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"There's no life in Olga's features,\nshe's just like a Van Dyck madonna.\nHer face is as round and rosy …","literalText":true,"sourceStartIndex":270,"sourceLineCount":3},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"… wave and rock,\npoetry and prose, ice and flame,\nare not as different as we are!","literalText":true,"sourceStartIndex":273,"sourceLineCount":3},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Now, alas, my days and nights\nand burning, solitary dreams,\nwill always be filled with his dear image!","literalText":true,"sourceStartIndex":276,"sourceLineCount":3},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"Everyone will start to whisper,\njoke, judge - not without malice!\nThere will be no end to the conjectures, etc.","literalText":true,"sourceStartIndex":279,"sourceLineCount":3},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Wave and rock, ice and flame …\n… poetry and prose, ice and flame,\nare not as different as we are …","literalText":true,"sourceStartIndex":282,"sourceLineCount":3},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"… as that stupid moon\non that dull horizon!","literalText":true,"sourceStartIndex":285,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Ceaselessly, with magical power,\neverything will speak to me of him,\nmy soul will be seared with the fire of love!","literalText":true,"sourceStartIndex":287,"sourceLineCount":3},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"… Joke, and judge - not without malice -\nand appoint him Tanya's suitor!","literalText":true,"sourceStartIndex":290,"sourceLineCount":2},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"… in our contrasting natures!","literalText":true,"sourceStartIndex":292,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"Her face is as round and rosy …","literalText":true,"sourceStartIndex":293,"sourceLineCount":1},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Wave and rock, ice and fire,\npoetry and prose …","literalText":true,"sourceStartIndex":294,"sourceLineCount":2},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"… as that stupid moon\non that dull horizon!","literalText":true,"sourceStartIndex":296,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Everything will speak to me of him,\nmy soul …","literalText":true,"sourceStartIndex":298,"sourceLineCount":2},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"There will be no end to the conjectures,\nand they'll appoint him …","literalText":true,"sourceStartIndex":300,"sourceLineCount":2}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"… are not as different as we are,","participants":["LENSKY","ONEGIN","TATYANA","OLGA"],"sourceStartIndex":302,"sourceLineCount":64,"turns":[{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"… are not as different as we are,\nin our contrasting natures!","literalText":true,"sourceStartIndex":302,"sourceLineCount":2},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"I should have chosen the other!","literalText":true,"sourceStartIndex":304,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"… will he seared by love's fire!","literalText":true,"sourceStartIndex":305,"sourceLineCount":1},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"… Tanya's suitor!","literalText":true,"sourceStartIndex":306,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Lensky approaches Olga. Onegin looks nonchalantly at Tatyana, who is standing with her eyes cast down; then he approaches her and engages her in conversation.\nto Olga","literalText":true,"sourceStartIndex":307,"sourceLineCount":2},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"How happy, how happy I am!\nI see you once again!","literalText":true,"sourceStartIndex":309,"sourceLineCount":2},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"We saw each other yesterday, I think!","literalText":true,"sourceStartIndex":311,"sourceLineCount":1},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Oh, yes,\nBut all the same, a whole long day\nhas gone by since we saw each other last!\nAn eternity!","literalText":true,"sourceStartIndex":312,"sourceLineCount":4},{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"Eternity!\nWhat a dreadful word!\nEternity, just one day …","literalText":true,"sourceStartIndex":316,"sourceLineCount":3},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"Yes, a dreadful word,\nbut not for my love!","literalText":true,"sourceStartIndex":319,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Olga and Lensky stroll off into the garden.\nto Tatyana","literalText":true,"sourceStartIndex":321,"sourceLineCount":2},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"Tell me,\nis it not dreadfully boring for you\nhere in the depths of the country,\nwhich, though lovely, is so far away?\nI don't suppose you get much amusement.","literalText":true,"sourceStartIndex":323,"sourceLineCount":5},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"I read a great deal …","literalText":true,"sourceStartIndex":328,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"It's true\nthat reading provides abundant food\nfor thought and feeling,\nbut one can't sit over a book the whole time!","literalText":true,"sourceStartIndex":329,"sourceLineCount":4},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"I daydream sometimes, strolling in the garden.","literalText":true,"sourceStartIndex":333,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"What do you dream about?","literalText":true,"sourceStartIndex":334,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Dreams have been my companions\nsince my earliest days.","literalText":true,"sourceStartIndex":335,"sourceLineCount":2},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"I see vou're a terrible dreamer!\nI used to be the same at one time.","literalText":true,"sourceStartIndex":337,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"They stroll away; Olga and Lensky return.","literalText":true,"sourceStartIndex":339,"sourceLineCount":1},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"I love you,\nI love you, Olga, as only\na poet's frantic heart\ncan still be fated to love.\nAlways, everywhere, one dream alone,\none constant longing,\none insistent sadness!\nAs a boy I was captivated by you,\nwhen heartache was still unknown;\nI witnessed, with tender emotion,\nyour childish games.\nBeneath the grove's protecting boughs\nI shared those games.\nAh,\nI love you,\nI love you with that love\nknown only to a poet's heart.\nFor you alone I dream.\nfor you alone I long,\nyou are my joy and my suffering.\nI love you,\nI love you, eternally, and nothing -\nnot the chilling distance,\nthe hour of parting, nor pleasure's clamour -\ncan quench that heart\naflame with love's virgin fire!","literalText":true,"sourceStartIndex":340,"sourceLineCount":26}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"In rural tranquillity …","participants":["OLGA","LENSKY","LARINA","FILIPYEVNA","ONEGIN","TATYANA"],"sourceStartIndex":366,"sourceLineCount":61,"turns":[{"speaker":"OLGA","speakerTranslation":"OLGA","original":"","translation":"In rural tranquillity …\n… we grew up together;\nand do you remember how our parents\ndestined us, even as children, for cach other?","literalText":true,"sourceStartIndex":366,"sourceLineCount":4},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"I love you! …\nI love you, I love you!","literalText":true,"sourceStartIndex":370,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Mme Larina and Filipyevna come out onto the terrace. It has grown darker, and within minutes night will have fallen.","literalText":true,"sourceStartIndex":372,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Ah, there you are!\nBut wherever has Tanya got to?","literalText":true,"sourceStartIndex":373,"sourceLineCount":2},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"She must be strolling by the lake with our guest;\nI'll go and call her.","literalText":true,"sourceStartIndex":375,"sourceLineCount":2},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"And tell her from me\nthat it's time to come indoors\nand let our hungry guests take pot-luck at table!","literalText":true,"sourceStartIndex":377,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Filipyevna leaves. To Lensky.","literalText":true,"sourceStartIndex":380,"sourceLineCount":1},{"speaker":"LARINA","speakerTranslation":"LARINA","original":"","translation":"Please come in.","literalText":true,"sourceStartIndex":381,"sourceLineCount":1},{"speaker":"LENSKY","speakerTranslation":"LENSKY","original":"","translation":"We're coming","literalText":true,"sourceStartIndex":382,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Mme Larina, Olga and Lensky enter the house. Tatyana and Onegin return, followed by Filipyevna who is trying to eavesdrop on their conversation. Tatyana is still painfully shy.","literalText":true,"sourceStartIndex":383,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"My uncle was a man of the highest principels;\nwhen he finally took to his bed\nhe forced the respect of all\nand it was the best thing he could do.\nMay others profit from his example!\nBut, my God, what a bore it was,\nsitting by an invalid day and night,\nnever daring to move a step away!","literalText":true,"sourceStartIndex":384,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"following them at a distance","literalText":true,"sourceStartIndex":392,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"There goes my little dove,\nwith meekly drooping head, downcast eyes.\nShe's dread fully shy!\nI wonder!\nSuppose she's taken a fancy to this new young man? …","literalText":true,"sourceStartIndex":393,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She enters the house, thoughtfully shaking her head.\nTatyana's room. It is very simply furnished with oldfashioned white wooden chairs, a chest of drawers with a mirror, a bookshelf beside the bed and a table with writing materials beneath the window.\nTatyana, in a white nightdress, is sitting before her mirror, lost in thought. Filipyevna stands beside her.","literalText":true,"sourceStartIndex":398,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Well, I've let my tongue run on!\nIt's time for bed, Tanya,\nI'll wake you early for mass;\ngo to sleep quickly.","literalText":true,"sourceStartIndex":401,"sourceLineCount":4},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"I’m not sleepy, nurse, it's so stuffy in here!\nOpen the window and come and sit by me.","literalText":true,"sourceStartIndex":405,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Filipyevna opens the window and sits on a chair near Tatyana.","literalText":true,"sourceStartIndex":407,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Why, Tanya, what's the matter with you?","literalText":true,"sourceStartIndex":408,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"I'm bored.\nLet's talk about the old days.","literalText":true,"sourceStartIndex":409,"sourceLineCount":2},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"But what about them, Tanya?\nI used to know any number\nof old tales and fairy stories\nabout evil spirits and beautiful maidens,\nbut now my memory's gone:\nI've forgotten all I knew, that's a fact!\nI'm getting old.\nDecrepit.","literalText":true,"sourceStartIndex":411,"sourceLineCount":8},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Tell me, nurse,\nabout your past:\nwere you in love when you were young?","literalText":true,"sourceStartIndex":419,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Get along with you, Tanya! In those days\none didn't talk of love,\nor my late mother-in-law\nwould have chased me from the face of the earth!","literalText":true,"sourceStartIndex":422,"sourceLineCount":4},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Then how did you get married, nurse?","literalText":true,"sourceStartIndex":426,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"It was God's will, I suppose! My Vanya","participants":["FILIPYEVNA","TATYANA"],"sourceStartIndex":427,"sourceLineCount":65,"turns":[{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"It was God's will, I suppose! My Vanya\nwas even younger than me, my love,\nand I was only thirteen!\nFor a week or two the marriage broker\nkept calling on my parents, and finally\nmy father gave his consent.\nI cried bitterly with fright;\nI wept when they undid my maiden plait\nand led me with songs to the church.\nAnd I found myself installed in a strange family …\nBut you're not listening to me!","literalText":true,"sourceStartIndex":427,"sourceLineCount":11},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Oh nurse, nurse, I'm consumed with longing,\nI’m all upset, my dear;\nI’m ready to burst into tears.","literalText":true,"sourceStartIndex":438,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"You’re not well, my child;\nLord have mercy on us!\nLet me sprinkle you with holy water.\nYou're feverish.","literalText":true,"sourceStartIndex":441,"sourceLineCount":4},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"I'm not ill,\nI … Do you know, nurse, … I'm … in love …\nLeave me, leave me …\nI’m in love …","literalText":true,"sourceStartIndex":445,"sourceLineCount":4},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"But of course …","literalText":true,"sourceStartIndex":449,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Go, leave me alone.\nGive me a pen and some paper, nurse,\nand move the table up; I'll soon go to bed.","literalText":true,"sourceStartIndex":450,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Filipyevna does as Tatyana has asked, then shuts the window, draws the curtains and kisses her good night.","literalText":true,"sourceStartIndex":453,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Good night.","literalText":true,"sourceStartIndex":454,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Sleep well","literalText":true,"sourceStartIndex":455,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She goes out. Tatyana remains sunk in thought, then rises in a state of great agitation with an expression of determination on her face.","literalText":true,"sourceStartIndex":456,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Let me perish, but first\nlet me summon, in dazzling hope,\nbliss as yet unknown.\nLife's sweetness is known to me!\nI drink the magic potion of desire!\nI am beset by visions!\nEverywhere, everywhere I look,\nI see my fatal tempter!\nWherever I look, I see him!","literalText":true,"sourceStartIndex":457,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She goes to the writing table, sits down, writes, then pauses.","literalText":true,"sourceStartIndex":466,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"No, that's all wrong!\nI'll begin again!","literalText":true,"sourceStartIndex":467,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"she tears up the unfinished letter","literalText":true,"sourceStartIndex":469,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Ah, what's the matter with me! I'm all on fire!\nI don't know how to begin!","literalText":true,"sourceStartIndex":470,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She writes, then pauses and reads it over.","literalText":true,"sourceStartIndex":472,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"'I write to you, - and then?\nWhat more is there to say?\nNow, I know, it is within your power\nto punish me with disdain!\nBut if you nourish one grain of pity\nfor my unhappy lot,\nyou will not abandon me.\nAt first I wished to remain silent;\nthen, believe me, you would never\nhave known my shame,\nnever!'","literalText":true,"sourceStartIndex":473,"sourceLineCount":11},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She puts the letter aside.","literalText":true,"sourceStartIndex":484,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"O yes, I swore to lock within my breast\nthis avowal of a mad and ardent passion.\nAlas, I have not the strength to subdue my heart!\nCome what may, I am prepared!\nI will confess all! Courage!\nHe shall know all!","literalText":true,"sourceStartIndex":485,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She writes.","literalText":true,"sourceStartIndex":491,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"'Why, oh why did you visit us?","participants":["TATYANA"],"sourceStartIndex":492,"sourceLineCount":62,"turns":[{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"'Why, oh why did you visit us?\nBuried in this remote countryside,\nI should never have known you,\nnor should I have known this torment.\nThe turbulence of a youthful heart,\ncalmed by time, who knows? -\nmost likely I would have found another,\nhave proved a faithful wife\nand virtuous mother…'","literalText":true,"sourceStartIndex":492,"sourceLineCount":9},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She becomes lost in thought, then rises suddenly.","literalText":true,"sourceStartIndex":501,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Another! No, not to any other in the world\nwould I have given my heart!\nIt is decreed on high,\nIt is the will of heaven: I am yours!\nMy whole life has been a pledge\nof this inevitable encounter;\nI know this: God sent you to me,\nyou are my keeper till the grave!\nYou appeared before me in my dreams;\nas yet unseen, you were already dear,\nyour wondrous gaze filled me with longing,\nyour voice resounded in my heart\nlong ago … no, it was no dream!\nAs soon as you arrived, I recognized you,\nI almost swooned, began to blaze with passion,\nand to myself I said: 'Tis he!\n'Tis he!\nI know it! I have heard you …\nHave you not spoken to me in the silence\nwhen I visited the poor\nor sought in prayer some solace\nfor the anguish of my soul?\nAnd just this very moment,\nwas it not you, dear vision,\nthat flamed in the limpid darkness,\nstooped gently at my bedside\nand with joy and love\nwhispered words of hope?","literalText":true,"sourceStartIndex":502,"sourceLineCount":28},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She returns to the table and sits down again to write.","literalText":true,"sourceStartIndex":530,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"'Who are you'? My guardian angel\nor a wily tempter?\nPut my doubts at rest.\nMaybe this is all an empty dream,\nthe self?deception of an inexperienced soul,\nand something quite different is to be …'","literalText":true,"sourceStartIndex":531,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She rises again and paces pensively to and fro.","literalText":true,"sourceStartIndex":537,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"But so be it! My fate\nhenceforth I entrust to you;\nin tears before you,\nyour protection I implore,\nI implore.\nImagine: I am all alone here!\nNo one understands me!\nI can think no more,\nand must perish in silence!\nI wait for you,\nI wait for you! Speak the word\nto revive my heart's fondest hopes\nor shatter this oppressive dream\nwith, alas, the scorn,\nalas, the scorn I have deserved!","literalText":true,"sourceStartIndex":538,"sourceLineCount":15},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She goes swiftly to the table, hurriedly finishes the letter and signs and seals it.","literalText":true,"sourceStartIndex":553,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"Finished! It's too frightening to read over,","participants":["TATYANA","FILIPYEVNA"],"sourceStartIndex":554,"sourceLineCount":59,"turns":[{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Finished! It's too frightening to read over,\nI swoon from shame and fear,\nbut his honour is my guarantee\nand in that I put my trust!","literalText":true,"sourceStartIndex":554,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"She goes to the window and draws aside the curtains. The room is immediately flooded with a rosy dawnlight. A shepherd's pipe is heard in the distance.","literalText":true,"sourceStartIndex":558,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Ah, night is past,\neverything is awake …\nand the sun is rising.\nThe shepherd is playing his pipe …\nEverything is peaceful.\nWhile I … I …","literalText":true,"sourceStartIndex":559,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The door opens softly and Filipyevna enters the room.","literalText":true,"sourceStartIndex":565,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"It's time, my child! Get up!\nWhy, you're up already, my pretty one!\nMy little early bird!\nI was so anxious last night …\nWell, my child, thank God you're well!\nNot a trace of last night's upset.\nYour cheeks are red as poppies!","literalText":true,"sourceStartIndex":566,"sourceLineCount":7},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Oh, nurse, be a darling …","literalText":true,"sourceStartIndex":573,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Of course, pet, tell me what you want.","literalText":true,"sourceStartIndex":574,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Don't think … truly … don't suspect …\nbut you see … oh, don't say no!","literalText":true,"sourceStartIndex":575,"sourceLineCount":2},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"My dearest, as God's my witness!","literalText":true,"sourceStartIndex":577,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Then, send your grandson, on the quiet,\nwith this note to O … to that …\nto our neighbour, and tell him\nnot to breathe a word\nand not to mention my name.","literalText":true,"sourceStartIndex":578,"sourceLineCount":5},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"To whom, my dear?\nI'm not as bright as I was!\nWe've lots of neighbours round about,\ndo you want me to go through them all?\nWhich one do you mean? Talk sense!","literalText":true,"sourceStartIndex":583,"sourceLineCount":5},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"How dense you are, nurse!","literalText":true,"sourceStartIndex":588,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Dear heart, I'm getting old!\nI’m old; my wits are dull, Tanya;\nbut in the old days I was bright enough.\nIn the old days, one word from the master …","literalText":true,"sourceStartIndex":589,"sourceLineCount":4},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"Oh, nurse, nurse, none of that matters!\nWhat do I want with your wits?\nYou see nurse, it's about a letter …","literalText":true,"sourceStartIndex":593,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Well, all right, all right!","literalText":true,"sourceStartIndex":596,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"What do I want with your wits, nurse …","literalText":true,"sourceStartIndex":597,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Don't be angry, dear heart!\nYou know how slow I am.","literalText":true,"sourceStartIndex":598,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"… To Onegin …","literalText":true,"sourceStartIndex":600,"sourceLineCount":1},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"All right, all right: I understand!","literalText":true,"sourceStartIndex":601,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"… to Onegin …\n… with a letter …\n… to Onegin, send your grandson, nurse!","literalText":true,"sourceStartIndex":602,"sourceLineCount":3},{"speaker":"FILIPYEVNA","speakerTranslation":"FILIPYEVNA","original":"","translation":"Well, well, don't be angry, dear heart!\nYou know I'm slow!\n… Gracious, why have you turned pale again?","literalText":true,"sourceStartIndex":605,"sourceLineCount":3},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"It's nothing, nurse, really nothing!\nGo and send your grandson!","literalText":true,"sourceStartIndex":608,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The nurse takes the letter, and after some hesitation, finally signifies that she understands and leaves.\nTatyana sits at the table and, resting her elbows upon it, again becomes lost in thought.\nAnother part of the garden of the Larin estate. Thick lilac and acacia bushes, neglected flower beds and an old wooden bench. Servant girls, picking fruit in the background, sing as they work.","literalText":true,"sourceStartIndex":610,"sourceLineCount":3}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"Pretty maidens,","participants":["SERVANT GIRLS","TATYANA","ONEGIN"],"sourceStartIndex":613,"sourceLineCount":49,"turns":[{"speaker":"SERVANT GIRLS","speakerTranslation":"SERVANT GIRLS","original":"","translation":"Pretty maidens,\ndear companions,\ncome on out to play, girls!\nTrip merrily, my friends,\nand sing a song,\na favourite song\nto lure a handsome lad\nto join our dance!\nWhen the handsome lad is lured,\nwhen he approaches us,\nlet's run away, my friends,\npelting him with cherries,\nwith cherries, with berries,\nwith redcurrants!\nDon't you come eavesdropping\non our favourite songs,\ndon't you come spying\non our girlish play!\nPretty maidens, etc.","literalText":true,"sourceStartIndex":613,"sourceLineCount":19},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The servant girls move off, their singing dies away.\nTatyana enters, running quickly, and sinks exhausted onto the bench.","literalText":true,"sourceStartIndex":632,"sourceLineCount":2},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"He's here! He's here, Eugene!\nDear God! Dear God, what must he have thought?\nWhat will he say? Oh why\ndid I obey my aching heart alone,\nand, lacking all self control,\nwrite him that letter!\nIndeed, my heart now tells me\nthat my fatal tempter\nwill only laugh at me!\nOh my God! How miserable I am,\nhow contemptible!\nFootsteps … they are drawing closer …\nYes, it is he, it is he!","literalText":true,"sourceStartIndex":634,"sourceLineCount":13},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"Onegin enters. Tatyana leaps to her feet and stands with lowered head as he approaches.","literalText":true,"sourceStartIndex":647,"sourceLineCount":1},{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"You wrote to me.\nDon't deny it. I have read\nthe avowal of a trusting heart,\nthe outpouring of an innocent love;\nyour candour touched me deeply.\nIt has stirred\nfeelings long since dormant.\nI won't commend you for this,\nBut I will repay you\nwith an equally guileless avowal.\nHear my confession,\nthen judge me as you will!","literalText":true,"sourceStartIndex":648,"sourceLineCount":12},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"collapsing again onto the bench","literalText":true,"sourceStartIndex":660,"sourceLineCount":1},{"speaker":"TATYANA","speakerTranslation":"TATYANA","original":"","translation":"O God! How humiliating and how painful!","literalText":true,"sourceStartIndex":661,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"","translatedTitle":"If I wished to pass my life","participants":["ONEGIN","SERVANT GIRLS"],"sourceStartIndex":662,"sourceLineCount":42,"turns":[{"speaker":"ONEGIN","speakerTranslation":"ONEGIN","original":"","translation":"If I wished to pass my life\nwithin the confines of the family circle,\nand a kindly fate had decreed for me\nthe role of husband and father,\nthen, most like, I would not choose\nany other bride than you.\nBut I was not made for wedded bliss,\nit is foreign to my soul,\nyour perfections are vain,\nI am quite unworthy of them.\nBelieve me, I give you my word,\nmarriage would be a torment for us.\nNo matter how much I loved you,\nhabit would kill that love.\nJudge what a thorny bed of roses\nHymen would prepare for us,\nand, perhaps, to be endured at length!\nOne cannot return to dreams and youth,\nI cannot renew my soul!\nI love you with a brother's love,\na brother's love\nor, perhaps, more than that!\nPerhaps, perhaps more than that!\nListen to me without getting angry,\nmore than once will a girl exchange\none passing fancy for another.\nLearn to control your feelings; …\n… Not everyone will understand you as I do.\nInexperience leads to disaster!","literalText":true,"sourceStartIndex":662,"sourceLineCount":29},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"in the distance","literalText":true,"sourceStartIndex":691,"sourceLineCount":1},{"speaker":"SERVANT GIRLS","speakerTranslation":"SERVANT GIRLS","original":"","translation":"Pretty maidens,\ndear companions,\ncome on out to play, girls! …\n… Trip it merrily, my friends.\nWhen a handsome lad is lured,\nwhen he approaches us,\nlet's run away, my friends,\npelting him with cherries.\nDon't you come eavesdropping,\ndon't you come spying\non our girlish play!","literalText":true,"sourceStartIndex":692,"sourceLineCount":11},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"","translation":"The voices of the servant girls die away. Onegin offers Tatyana his arm; after giving him a long, imploring look, she rises mechanically, accepts his arm and they leave slowly.","literalText":true,"sourceStartIndex":703,"sourceLineCount":1}]}]}];
